public class MultipleSummerCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(MultipleSummer impl) {
        try {
            return MultipleSummerChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectSummer()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectSummer()));
        check("rejects the off-by-one that includes the limit itself", false, verdict(new InclusiveSummer()));
        check("rejects the version that counts multiples of 15 twice", false, verdict(new DoubleCountSummer()));
        check("rejects the version that forgets multiples of 5", false, verdict(new ThreesOnlySummer()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectSummer implements MultipleSummer {
    public int sumBelow(int limit) {
        int total = 0;
        for (int n = 1; n < limit; n++) {
            if (n % 3 == 0 || n % 5 == 0) total += n;
        }
        return total;
    }
}

class AlsoCorrectSummer implements MultipleSummer {
    public int sumBelow(int limit) {
        int total = 0;
        for (int n = limit - 1; n > 0; n--) {
            boolean byThree = n % 3 == 0;
            boolean byFive = n % 5 == 0;
            if (byThree || byFive) total += n;
        }
        return total;
    }
}

class InclusiveSummer implements MultipleSummer {
    public int sumBelow(int limit) {
        int total = 0;
        for (int n = 1; n <= limit; n++) {
            if (n % 3 == 0 || n % 5 == 0) total += n;
        }
        return total;
    }
}

class DoubleCountSummer implements MultipleSummer {
    public int sumBelow(int limit) {
        int total = 0;
        for (int n = 1; n < limit; n++) {
            if (n % 3 == 0) total += n;
            if (n % 5 == 0) total += n;
        }
        return total;
    }
}

class ThreesOnlySummer implements MultipleSummer {
    public int sumBelow(int limit) {
        int total = 0;
        for (int n = 1; n < limit; n++) {
            if (n % 3 == 0) total += n;
        }
        return total;
    }
}

