 */
interface MultipleSummer {
    /* Provided -- do not edit. */
    int sumBelow(int limit);
}

public class MultipleSummerChecker {

    public static boolean isCorrect(MultipleSummer impl) {
        try {
            if (impl.sumBelow(10) != 23) return false;
            if (impl.sumBelow(16) != 60) return false;
            if (impl.sumBelow(15) != 45) return false;
            if (impl.sumBelow(0) != 0) return false;
            if (impl.sumBelow(-4) != 0) return false;
            if (impl.sumBelow(1) != 0) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
